questionvariables.text:
/* Q1 : Bouton radio (1pt) */
ta1_all:[["1",true,"Une monarchie constitutionnelle encadrée par la toute première Constitution écrite de l'histoire du pays."],["2",true,"Une monarchie limitée où le roi détient le pouvoir exécutif et l'Assemblée unique exerce le pouvoir législatif."],["3",true,"Un régime de monarchie représentative fondé sur le principe de la souveraineté nationale et le suffrage censitaire."],["4",true,"Un système monarchique rénové associant un souverain héréditaire à une assemblée de représentants des citoyens."],["5",false,"Une république démocratique garantissant le suffrage universel masculin pour l'élection des nouveaux députés."],["6",false,"Une monarchie parlementaire calquée sur le modèle britannique permettant aux ministres d'être révoqués par les députés."],["7",false,"Une démocratie directe accordant aux assemblées primaires de citoyens le droit de veto sur les lois votées."],["8",false,"Une dictature de salut public confiant l'intégralité des pouvoirs régaliens à un comité restreint de députés."],["9",false,"Un empire constitutionnel conciliant l'autorité d'un souverain fort et les libertés individuelles de 1789."],["10",false,"Une république oligarchique dirigée par un Directoire de cinq membres élus parmi les plus riches propriétaires."],["11",false,"Une monarchie absolue de droit divin réaffirmant la prérogative royale contre les empiétements de l'Assemblée."],["12",false,"Une confédération de républiques autonomes calquée sur le système fédéral des jeunes États-Unis d'Amérique."],["13",false,"Un régime présidentiel fort accordant au chef de l'État le pouvoir de dissoudre l'Assemblée à tout moment."]];
fb1:[["1","En septembre 1791, l'Assemblée nationale constituante promulgue la première Constitution française, maintenant le roi Louis XVI à la tête de l'exécutif mais transférant la souveraineté à la Nation incarnée par l'Assemblée."],["2","La Constitution de 1791 organise une séparation des pouvoirs rigide où le monarque gouverne et applique les lois votées par les représentants élus de la Nation."],["3","Les constituants refusent la démocratie directe et instaurent un système représentatif où seuls les citoyens payant un certain niveau d'impôt participent au vote."],["4","Le compromis de 1791 conserve la figure royale pour assurer la stabilité de l'État tout en soumettant l'autorité du roi au respect d'une charte constitutionnelle supérieure."],["5","Confusion chronologique et idéologique. En 1791, la majorité des députés est hostile à l'idée républicaine, assimilée à l'anarchie. La Première République n'est proclamée qu'en septembre 1792, et le suffrage universel n'apparaît qu'à ce moment."],["6","Erreur technique majeure. C'est le piège de l'exercice. La Constitution de 1791 opte pour une séparation stricte et rigide des pouvoirs. Le roi choisit ses ministres en dehors de l'Assemblée et celle-ci ne peut pas renverser le gouvernement. Le régime parlementaire n'apparaît en France qu'au XIXe siècle."],["7","Contresens conceptuel. Les constituants de 1791 se méfient du peuple et rejettent la démocratie directe. Ils mettent en place un régime représentatif strict où la souveraineté est déléguée exclusivement aux députés de la Nation."],["8","Anachronisme de contexte. Ce mode de gouvernement d'exception correspond à la période de la Terreur et au Comité de salut public créés en 1793. En 1791, l'Assemblée cherche au contraire à limiter l'arbitraire par des lois fixes."],["9","Confusion de régime. Le terme d'Empire renvoie à l'expérience de Napoléon Bonaparte à partir de 1804. En 1791, la France demeure juridiquement et symboliquement un royaume, et le titre de Louis XVI devient \"roi des Français\"."],["10","Confusion chronologique. La république oligarchique et le Directoire correspondent à la Constitution de l'an III, mise en place en 1795 pour sortir de la Terreur. En 1791, le pouvoir exécutif reste entre les mains du roi."],["11","Méconnaissance de la rupture de 1789. La monarchie absolue est détruite dès l'été 1789 lors du serment du Jeu de paume et de la nuit du 4 août. En 1791, le roi ne tient plus son pouvoir de Dieu mais de la Nation et de la loi."],["12","Erreur de modèle politique. Si les révolutionnaires admirent la révolution américaine, ils rejettent le fédéralisme. L'Assemblée constituante réaffirme l'unité et l'indivisibilité du royaume, centralisé par la création des départements."],["13","Anachronisme institutionnel. La notion de régime présidentiel et le droit de dissolution n'existent pas dans l'esprit des constituants de 1791. De plus, le roi possède un droit de veto suspensif mais ne peut en aucun cas dissoudre l'Assemblée."]];
pV1:sublist(ta1_all,lambda([ex],second(ex)=true));
pF1:sublist(ta1_all,lambda([ex],second(ex)=false));
ta1:random_permutation(append(rand_selection(pV1,1),rand_selection(pF1,4-1)));
la_vraie1:first(sublist(ta1,lambda([ex],second(ex)=true)));
texte_vrai1:third(la_vraie1);
fb_vrai1:assoc(first(la_vraie1),fb1);
